void reset_theme(void)
{
    settingstheme_state_param_t theme_state;
    s32             ret;

    theme_state.theme_type = 0;

    for (uint8_t i = 0; i < 3; i++) {
        theme_state.theme[i].call = 0;
        theme_state.theme[i].level = 7;
        theme_state.theme[i].message = 0;
        theme_state.theme[i].poweronoff = 1;
        }

    theme_state.music_level = 7;
    ret                 = aic_md_write(MD_ID_SETTING_THEME,sizeof(settingstheme_state_param_t),&theme_state);

    if (ret) {
        APP_LOGI("reset_theme read net cfg error 0x%x\n",ret);
        }
}


uint8_t power_on_off_sound_status(void)
{
    settingstheme_state_param_t theme_state;
    s32             ret;

    ret                 = aic_md_read(MD_ID_SETTING_THEME,sizeof(settingstheme_state_param_t),&theme_state);

    if (ret) {
        APP_LOGI("reset_theme read net cfg error 0x%x\n",ret);
        }

    if (theme_state.theme_type == 3)
        return 0; // 静音

    if (theme_state.theme[theme_state.theme_type].poweronoff == 0)
        return 0; // 静音

    else 
        return 1; // 开机有铃声
}


