static uint32_t get_setting_theme_item_ring_childId(uint32_t child_cnt)
{
    /*Modify manually*/
    lv_obj_t *      ui_setting_child = NULL;
    uint32_t        child_id;

    for (child_id = 0; child_id < child_cnt; child_id++) {
        ui_setting_child    = lv_obj_get_child(ui_FpSettingsThemeItemRingIndex,child_id);

        if (lv_obj_has_state(ui_setting_child,LV_STATE_FOCUSED)) {
            break;
            }

        }

    if (child_id >= child_cnt) {
        child_id            = 0;
        }

    //__inf("get_setting_childId:%d,child_cnt:%d\r\n",child_id,child_cnt);
    return child_id;
}


void settings_theme_app_item_ring_ui_event_actions(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    //lv_obj_t * target = lv_event_get_target(e);
    uint32_t        child_cnt = lv_obj_get_child_cnt(ui_FpSettingsThemeItemRingIndex);
    uint32_t        child_id = get_setting_theme_item_ring_childId(child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;

    __inf("settings_theme_app_ui_event_actions 00 =%d\r\n",event_code);

    switch (event_code)
    {
        case LV_EVENT_SCREEN_LOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_add_obj(lv_group_get_default(),obj);
                    lv_group_focus_obj(obj);
                    }

                }
            break;

        case LV_EVENT_SCREEN_UNLOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_remove_obj(obj);
                    }
                }
            break;

        case LV_EVENT_KEY:
            {
                uint32_t        key = lv_event_get_key(e);

                __inf("settings_theme_app_ui_event_actions111 LV_EVENT_KEY:%d\r\n",key);

                if (key == LV_KEY_UP) {
                    //__inf("LV_KEY_UP,child_id:%d,child_cnt:%d\r\n",child_id,child_cnt);
                    if (child_id != 0) {
                        pre_focus_obj       = lv_obj_get_child(ui_FpSettingsThemeItemRingIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);



                        get_focus_obj       = lv_obj_get_child(ui_FpSettingsThemeItemRingIndex,child_id - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        if ((child_id - 1) == 0) {
                            lv_obj_scroll_to_y(ui_FpSettingsThemeItemRingIndex,0,LV_ANIM_OFF);

                            }
                        else {
                            lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);

                            }

                        }
                    else {
                        pre_focus_obj       = lv_obj_get_child(ui_FpSettingsThemeItemRingIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        get_focus_obj       = lv_obj_get_child(ui_FpSettingsThemeItemRingIndex,child_cnt - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        //__inf("get_focus_obj :%d\r\n",lv_obj_has_state(get_focus_obj, LV_STATE_FOCUSED));
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);

                        }

                    child_id            = get_setting_theme_item_ring_childId(child_cnt);
                    settingstheme_state_param_t theme_state;
                    s32             ret;

                    ret                 = aic_md_read(MD_ID_SETTING_THEME,sizeof(settingstheme_state_param_t),
                        &theme_state);

                    if (ret) {
                        APP_LOGI("read net cfg error 0x%x\n",ret);
                        }

                    settings_fp_flow_set_master_volume(theme_state.theme[ui_FpSettingsSelected].level,child_id,0,
                        NULL);
                    }
                else if (key == LV_KEY_DOWN) {

                    if (child_id != child_cnt - 1) {
                        pre_focus_obj       = lv_obj_get_child(ui_FpSettingsThemeItemRingIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        get_focus_obj       = lv_obj_get_child(ui_FpSettingsThemeItemRingIndex,child_id + 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);

                        }
                    else {
                        pre_focus_obj       = lv_obj_get_child(ui_FpSettingsThemeItemRingIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        get_focus_obj       = lv_obj_get_child(ui_FpSettingsThemeItemRingIndex,0);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        lv_obj_scroll_to_y(ui_FpSettingsThemeItemRingIndex,0,LV_ANIM_OFF);

                        }

                    child_id            = get_setting_theme_item_ring_childId(child_cnt);
                    settingstheme_state_param_t theme_state;
                    s32             ret;

                    ret                 = aic_md_read(MD_ID_SETTING_THEME,sizeof(settingstheme_state_param_t),
                        &theme_state);

                    if (ret) {
                        APP_LOGI("read net cfg error 0x%x\n",ret);
                        }

                    settings_fp_flow_set_master_volume(theme_state.theme[ui_FpSettingsSelected].level,child_id,0,
                        NULL);
                    }
                else if (key == LV_KEY_LEFT) {

                    }
                else if (key == LV_KEY_DEL) {
                    uint8_t         index = ring_selected; // 回退到设置的情景模式选项

                    ps_data_msg_send_call_ring_stop(NULL);
                    alv_am_win_jump_action(NULL,"set_theme_item",(void *) &index);
                    }
                else if ((key == LV_KEY_ESC) || (key == LV_KEY_ENTER)) {
                    uint8_t         index = ring_selected; // 
                    settingstheme_state_param_t theme_state;
                    s32             ret;

                    ret                 = aic_md_read(MD_ID_SETTING_THEME,sizeof(settingstheme_state_param_t),
                        &theme_state);

                    if (ret) {
                        APP_LOGI("read net cfg error 0x%x\n",ret);
                        }

                    if (ring_selected == 1)
                        theme_state.theme[ui_FpSettingsSelected].call = child_id;
                    else 
                        theme_state.theme[ui_FpSettingsSelected].message = child_id;

                    ret                 = aic_md_write(MD_ID_SETTING_THEME,sizeof(settingstheme_state_param_t),
                        &theme_state);

                    if (ret) {
                        APP_LOGI("read net cfg error 0x%x\n",ret);
                        }

                    ps_data_msg_send_call_ring_stop(NULL);
                    alv_am_win_jump_action(NULL,"set_theme_item",(void *) &index);
                    }
                else if (key == LV_KEY_END) {
                    ps_data_msg_send_call_ring_stop(NULL);
                    alv_am_app_exit_action_all();
                    }

                }
            break;

        default:
            break;
        }


}


